	/** Restored from the pre-merge suite: a connected three-pattern component is never split by a Cartesian pair. */
	@Test
	void reorderJoinArgsNeverChoosesCartesianPairInsideConnectedComponent() throws Exception {
		StatementPattern first = new StatementPattern(Var.of("a"), Var.of("pA", VF.createIRI("ex:pA")),
				Var.of("bridgeAB"));
		StatementPattern middle = new StatementPattern(Var.of("bridgeAB"), Var.of("pB", VF.createIRI("ex:pB")),
				Var.of("bridgeBC"));
		StatementPattern last = new StatementPattern(Var.of("bridgeBC"), Var.of("pC", VF.createIRI("ex:pC")),
				Var.of("c"));

		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public boolean supportsJoinEstimation() {
				return true;
			}

			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression instanceof StatementPattern pattern) {
					return switch (predicate(pattern)) {
					case "ex:pA" -> 2.0d;
					case "ex:pB" -> 3.0d;
					case "ex:pC" -> 4.0d;
					default -> 10.0d;
					};
				}
				if (expression instanceof Join join) {
					Set<String> shared = new HashSet<>(join.getLeftArg().getBindingNames());
					shared.retainAll(join.getRightArg().getBindingNames());
					return shared.isEmpty() ? 1.0d : 100.0d;
				}
				return super.getCardinality(expression);
			}
		};
		Deque<TupleExpr> reordered = invokeReorderJoinArgs(new QueryJoinOptimizer(statistics, new EmptyTripleSource()),
				new ArrayDeque<>(List.of(first, middle, last)), Set.of());

		Set<String> prefixBindings = new HashSet<>();
		for (TupleExpr factor : reordered) {
			if (!prefixBindings.isEmpty()) {
				Set<String> shared = new HashSet<>(factor.getBindingNames());
				shared.retainAll(prefixBindings);
				assertThat(shared).as("each factor in a connected component must join the existing prefix")
						.isNotEmpty();
			}
			prefixBindings.addAll(factor.getBindingNames());
		}
	}

