	/** Restored from the pre-merge suite: a property path is a run member and is scheduled as the bridge. */
	@Test
	void reorderJoinArgsUsesPropertyPathAsBridgeBeforeDisconnectedPattern() throws Exception {
		StatementPattern selectiveStart = new StatementPattern(Var.of("root"),
				Var.of("startPredicate", VF.createIRI("ex:start")), Var.of("bridge"));
		StatementPattern disconnectedTarget = new StatementPattern(Var.of("target"),
				Var.of("targetPredicate", VF.createIRI("ex:target")), Var.of("targetValue", VF.createIRI("ex:value")));
		StatementPattern pathExpression = new StatementPattern(Var.of("pathSubject"),
				Var.of("pathPredicate", VF.createIRI("ex:next")), Var.of("pathObject"));
		ArbitraryLengthPath bridgePath = new ArbitraryLengthPath(Var.of("bridge"), pathExpression, Var.of("target"),
				1L);

		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public boolean supportsJoinEstimation() {
				return true;
			}

			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression == selectiveStart) {
					return 1.0d;
				}
				if (expression == disconnectedTarget) {
					return 10.0d;
				}
				if (expression instanceof Join join) {
					Set<String> shared = new HashSet<>(join.getLeftArg().getBindingNames());
					shared.retainAll(join.getRightArg().getBindingNames());
					return shared.isEmpty() ? 1_000.0d : 2.0d;
				}
				return super.getCardinality(expression);
			}
		};

		Deque<TupleExpr> reordered = invokeReorderJoinArgs(new QueryJoinOptimizer(statistics, new EmptyTripleSource()),
				new ArrayDeque<>(List.of(selectiveStart, disconnectedTarget, bridgePath)), Set.of());

		assertThat(reordered).containsExactly(selectiveStart, bridgePath, disconnectedTarget);
	}

	@Test
	void propertyPathInternalVariablesDoNotBridgeComponents() throws Exception {
		// the path expression reuses the name ?leaf internally; that must not connect {leaf q v} to the path
		StatementPattern selectiveStart = new StatementPattern(Var.of("root"),
				Var.of("startPredicate", VF.createIRI("ex:start")), Var.of("bridge"));
		StatementPattern pathExpression = new StatementPattern(Var.of("leaf"),
				Var.of("pathPredicate", VF.createIRI("ex:next")), Var.of("pathObject"));
		ArbitraryLengthPath bridgePath = new ArbitraryLengthPath(Var.of("bridge"), pathExpression, Var.of("target"),
				1L);
		StatementPattern island = new StatementPattern(Var.of("leaf"), Var.of("q", VF.createIRI("ex:q")),
				Var.of("v", VF.createIRI("ex:v")));

		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public boolean supportsJoinEstimation() {
				return true;
			}

			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression == selectiveStart) {
					return 100.0d;
				}
				if (expression == island) {
					return 1.0d;
				}
				if (expression instanceof Join join) {
					Set<String> shared = new HashSet<>(join.getLeftArg().getBindingNames());
					shared.retainAll(join.getRightArg().getBindingNames());
					shared.removeIf(name -> name.startsWith("_const_"));
					return shared.isEmpty() ? 100.0d : 5.0d;
				}
				return super.getCardinality(expression);
			}
		};

		Deque<TupleExpr> reordered = invokeReorderJoinArgs(new QueryJoinOptimizer(statistics, new EmptyTripleSource()),
				new ArrayDeque<>(List.of(selectiveStart, bridgePath, island)), Set.of());

		// {leaf q v} is its own component: it may lead (it is the cheapest), the path must still follow its start
		List<TupleExpr> order = new ArrayList<>(reordered);
		assertEquals(island, order.getFirst(), order.toString());
		assertTrue(order.indexOf(selectiveStart) < order.indexOf(bridgePath), order.toString());
	}

