	// ------------------------------------------------------------------ component policy details

	@Test
	void genuinelyDisconnectedComponentsMayStillBeOrderedByCostOnBothPaths() {
		// {a p1 b, b p2 c} and {x q1 y}: q1 is the cheapest, so develop's cost-first choice between components stays
		for (boolean pairwise : new boolean[] { false, true }) {
			Map<String, Double> byPredicate = Map.of("p1", 100.0d, "p2", 50.0d, "q1", 1.0d);
			TupleExpr query = new QueryRoot(
					new Join(new Join(sp("a", "p1", "b"), sp("b", "p2", "c")), sp("x", "q1", "y")));
			new QueryJoinOptimizer(new FixedStatistics(byPredicate, pairwise), new EmptyTripleSource())
					.optimize(query, null, EmptyBindingSet.getInstance());
			List<String> order = predicateOrder(query);
			assertEquals("q1", order.getFirst(), "pairwise=" + pairwise + " order=" + order);
			assertEquals(List.of("p2", "p1"), order.subList(1, 3),
					"pairwise=" + pairwise + ": the connected component is evaluated cheapest-first: " + order);
		}
	}

	@Test
	void prefixConnectedComponentMustNotSkipItsBridgeOnTheHeuristicPath() throws Exception {
		// prefix {s}; {s p ?o} bridges to {?o q ?z}; {x r y} is its own component and legal at any time
		StatementPattern bridge = sp("s", "p", "o");
		StatementPattern behindBridge = sp("o", "q", "z");
		StatementPattern island = sp("x", "r", "y");
		Map<TupleExpr, Double> cardinalityMap = Map.of(bridge, 1_000.0d, behindBridge, 1.0d, island, 500.0d);
		Map<TupleExpr, List<Var>> varsMap = Map.of(bridge, bridge.getVarList(), behindBridge,
				behindBridge.getVarList(), island, island.getVarList());
		Map<Var, Integer> varFreqMap = new HashMap<>();
		for (List<Var> vars : varsMap.values()) {
			for (Var var : vars) {
				varFreqMap.merge(var, 1, Integer::sum);
			}
		}
		QueryJoinOptimizer optimizer = new QueryJoinOptimizer(new EvaluationStatistics(), new EmptyTripleSource());
		Object joinVisitor = buildJoinVisitor(optimizer);
		setBoundVars(joinVisitor, Set.of("s"));
		Method selectNextTupleExpr = findDeclaredMethod(joinVisitor.getClass(), "selectNextTupleExpr", List.class,
				Map.class, Map.class, Map.class);
		selectNextTupleExpr.setAccessible(true);

		TupleExpr selected = (TupleExpr) selectNextTupleExpr.invoke(joinVisitor,
				new ArrayList<>(List.of(behindBridge, bridge, island)), cardinalityMap, varsMap, varFreqMap);
		assertThat(selected).as("{?o q ?z} shares a component with the prefix but is not connected to it yet")
				.isNotSameAs(behindBridge);

		TupleExpr selectedWithoutBridge = (TupleExpr) selectNextTupleExpr.invoke(joinVisitor,
				new ArrayList<>(List.of(behindBridge, island)), cardinalityMap, varsMap, varFreqMap);
		assertThat(selectedWithoutBridge)
				.as("once no ready candidate connects the component to the prefix, cost decides again")
				.isSameAs(behindBridge);
	}

